package com.rpb.reservation.workforce;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.workforce.scheduling.*;
import com.rpb.reservation.workforce.scheduling.bulk.*;
import com.rpb.reservation.workforce.scheduling.adjustment.*;
import static com.rpb.reservation.workforce.scheduling.SchedulingDtos.*;
import static com.rpb.reservation.workforce.scheduling.adjustment.BulkAdjustmentDtos.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;
class WorkforceBulkAdjustmentPostgresTest extends WorkforcePostgresTest {
 SchedulingRepository scheduling;BulkScheduleRepository bulk;ScheduleService schedules;BulkAdjustmentPlanService plans;BulkAdjustmentService changes;UUID first,second,early,late;List<UUID> ids;WorkforceAudit audit;WorkforceJson json;
 static final LocalDate DATE=LocalDate.of(2026,10,29);
 @BeforeEach void adjustmentSetup(TestInfo info){if(info.getTestMethod().orElseThrow().getDeclaringClass()!=WorkforceBulkAdjustmentPostgresTest.class)return;var mapper=new ObjectMapper().findAndRegisterModules();json=new WorkforceJson(mapper);audit=new WorkforceAudit(logs,mapper);scheduling=new SchedulingRepository(jdbc,json);bulk=new BulkScheduleRepository(jdbc,json);schedules=proxy(new ScheduleService(access,scheduling,repository,audit,clock));plans=proxy(new BulkAdjustmentPlanService(access,scheduling,bulk,json,clock));changes=proxy(new BulkAdjustmentService(access,scheduling,bulk,repository,plans,schedules,audit,json));first=UUID.randomUUID();employees.save(admin,store,first,command(0,List.of(store,sibling),company,null,null));second=cloneEmployee("E002");early=UUID.randomUUID();late=UUID.randomUUID();var shifts=proxy(new ShiftService(access,scheduling,audit));shifts.save(admin,store,early,new ShiftWrite(0L,"Early","09:00","17:00",false,"none",0,0,0,0,false,true));shifts.save(admin,store,late,new ShiftWrite(0L,"Late","18:00","23:00",false,"none",0,0,0,0,false,true));ids=new ArrayList<>();for(var employee:List.of(first,second)){var id=UUID.randomUUID();ids.add(id);schedules.save(admin,store,id,new ScheduleWrite(0L,employee,early,DATE,"scheduled"));}}
 UUID cloneEmployee(String no){var id=UUID.randomUUID();jdbc.update("insert into workforce_employees(id,tenant_id,employee_no,name,hire_date,status,company_id,company_effective_date,main_store_id,version,position_id) select ?,tenant_id,?,name,hire_date,status,company_id,company_effective_date,main_store_id,1,position_id from workforce_employees where id=?",id,no,first);for(var shop:List.of(store,sibling))jdbc.update("insert into workforce_work_stores(employee_id,tenant_id,store_id,started_on) values(?,?,?,'2026-10-01')",id,tenant,shop);return id;}
 Request request(){return new Request(DATE,early,late,ids.stream().map(id->new Target(id,1L)).toList());}
 @Test void previewIsReadonlyAndUpdatesOriginalIdsWithBoundIdempotentReceipt(){var before=jdbc.queryForList("select to_jsonb(s)::text from workforce_schedules s where tenant_id=? order by id",String.class,tenant);var p=plans.preview(admin,store,request());assertThat(p.ready()).isEqualTo(2);assertThat(jdbc.queryForList("select to_jsonb(s)::text from workforce_schedules s where tenant_id=? order by id",String.class,tenant)).isEqualTo(before);var input=new Commit(request(),p.fingerprint());var command=UUID.randomUUID();var result=changes.commit(admin,store,command,input);assertThat(result.updated()).isEqualTo(2);assertThat(result.scheduleIds()).containsExactlyInAnyOrderElementsOf(ids);assertThat(changes.commit(admin,store,command,input)).isEqualTo(result);for(var id:ids){var row=scheduling.find(tenant,id).orElseThrow();assertThat(row.version()).isEqualTo(2);assertThat(row.shiftId()).isEqualTo(late);}assertThat(jdbc.queryForObject("select count(*) from workforce_schedules where tenant_id=?",Long.class,tenant)).isEqualTo(2);assertThatThrownBy(()->changes.commit(admin,sibling,command,input)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(409);}
 @Test void occupiedOtherStoreAndLinkedAttendanceAreConflictsWithoutChangingHistory(){jdbc.update("insert into workforce_attendance_sessions(id,tenant_id,store_id,employee_id,schedule_id,in_at,version) select gen_random_uuid(),tenant_id,store_id,employee_id,id,start_at,1 from workforce_schedules where id=?",ids.getFirst());var other=UUID.randomUUID();proxy(new ShiftService(access,scheduling,audit)).save(admin,sibling,other,new ShiftWrite(0L,"Other","19:00","22:00",false,"none",0,0,0,0,false,true));schedules.save(admin,sibling,UUID.randomUUID(),new ScheduleWrite(0L,second,other,DATE,"scheduled"));var p=plans.preview(admin,store,request());assertThat(p.ready()).isZero();assertThat(p.items()).extracting(Item::reason).containsExactlyInAnyOrder("IN_USE","TIME_OVERLAP");assertThatThrownBy(()->changes.commit(admin,store,UUID.randomUUID(),new Commit(request(),p.fingerprint()))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);for(var id:ids)assertThat(scheduling.find(tenant,id).orElseThrow().version()).isEqualTo(1);}
 @Test void changedPreviewAndAuditFailureCannotPartiallyUpdate(){var p=plans.preview(admin,store,request());schedules.save(admin,store,ids.getFirst(),new ScheduleWrite(1L,first,early,DATE,"cancelled"));assertThatThrownBy(()->changes.commit(admin,store,UUID.randomUUID(),new Commit(request(),p.fingerprint()))).isInstanceOf(WorkforceException.class).extracting("code").isEqualTo("WORKFORCE_ADJUST_CHANGED");var fresh=plans.preview(admin,store,request());assertThat(fresh.ready()).isEqualTo(1);doThrow(new IllegalStateException("audit unavailable")).when(logs).append(any(com.rpb.reservation.common.scope.StoreScope.class),any());assertThatThrownBy(()->changes.commit(admin,store,UUID.randomUUID(),new Commit(request(),fresh.fingerprint()))).isInstanceOf(IllegalStateException.class);assertThat(scheduling.find(tenant,ids.get(1)).orElseThrow().version()).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from workforce_bulk_schedule_commands where tenant_id=?",Long.class,tenant)).isZero();}
 @Test void permissionsForeignSourceAndMultipleSegmentsCannotBeBypassed(){var worker=new com.rpb.reservation.walkin.api.CurrentActor(tenant,adminId,"staff",Set.of("store_staff"),Set.of("workforce.view"),Set.of(store));assertThatThrownBy(()->plans.preview(worker,store,request())).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);assertThatThrownBy(()->plans.preview(admin,sibling,request())).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);assertThatThrownBy(()->plans.preview(admin,store,new Request(DATE,early,late,List.of(new Target(UUID.randomUUID(),1L))))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(404);proxy(new ShiftService(access,scheduling,audit)).save(admin,store,early,new ShiftWrite(1L,"Early","18:00","20:00",false,"none",0,0,0,0,false,true));schedules.save(admin,store,UUID.randomUUID(),new ScheduleWrite(0L,first,early,DATE,"scheduled"));var p=plans.preview(admin,store,request());assertThat(p.items()).anyMatch(row->row.reason().equals("MULTIPLE_SEGMENTS"));assertThat(p.ready()).isEqualTo(1);}
 @Test void unchangedSourcesAreNotRewrittenAndConcurrentCommandsCannotDuplicate()throws Exception{var same=new Request(DATE,early,early,request().targets());assertThat(plans.preview(admin,store,same).unchanged()).isEqualTo(2);var input=new Commit(request(),plans.preview(admin,store,request()).fingerprint());var command=UUID.randomUUID();try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->changes.commit(admin,store,command,input));var b=pool.submit(()->changes.commit(admin,store,command,input));assertThat(a.get()).isEqualTo(b.get());}for(var id:ids)assertThat(scheduling.find(tenant,id).orElseThrow().version()).isEqualTo(2);}
 @Test void fiveHundredEmployeesAreUpdatedInPlaceWithoutTruncation(){new org.springframework.transaction.support.TransactionTemplate(tx).executeWithoutResult(status->{for(int n=2;n<500;n++){var employee=cloneEmployee("C"+n);var id=UUID.randomUUID();ids.add(id);schedules.save(admin,store,id,new ScheduleWrite(0L,employee,early,DATE,"scheduled"));}});var p=plans.preview(admin,store,request());assertThat(p.ready()).isEqualTo(500);assertThat(changes.commit(admin,store,UUID.randomUUID(),new Commit(request(),p.fingerprint())).updated()).isEqualTo(500);assertThat(jdbc.queryForObject("select count(*) from workforce_schedules where tenant_id=? and version=2 and shift_id=?",Long.class,tenant,late)).isEqualTo(500);}
 @Test void partialSuccessSkipsLinkedRecordAndManagerCannotEscapeStore(){jdbc.update("insert into workforce_attendance_sessions(id,tenant_id,store_id,employee_id,schedule_id,in_at,version) select gen_random_uuid(),tenant_id,store_id,employee_id,id,start_at,1 from workforce_schedules where id=?",ids.getFirst());var before=jdbc.queryForList("select to_jsonb(a)::text from workforce_attendance_sessions a where tenant_id=?",String.class,tenant);var managerId=account("store_manager",Set.of(store),Set.of("workforce.view"));var manager=new com.rpb.reservation.walkin.api.CurrentActor(tenant,managerId,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store));jdbc.update("insert into workforce_administrators(tenant_id,store_id,account_id,employee_manage,version) values(?,?,?,true,1)",tenant,store,managerId);var p=plans.preview(manager,store,request());assertThat(p.ready()).isEqualTo(1);var result=changes.commit(manager,store,UUID.randomUUID(),new Commit(request(),p.fingerprint()));assertThat(result.updated()).isEqualTo(1);assertThat(result.conflicts()).isEqualTo(1);assertThat(scheduling.find(tenant,ids.getFirst()).orElseThrow().version()).isEqualTo(1);assertThat(jdbc.queryForList("select to_jsonb(a)::text from workforce_attendance_sessions a where tenant_id=?",String.class,tenant)).isEqualTo(before);assertThatThrownBy(()->plans.preview(manager,sibling,request())).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}
 @Test void targetOrOccupancyChangesInvalidatePreviewBeforeAnyWrite(){var input=new Commit(request(),plans.preview(admin,store,request()).fingerprint());proxy(new ShiftService(access,scheduling,audit)).save(admin,store,late,new ShiftWrite(1L,"Late changed","18:30","23:00",false,"none",0,0,0,0,false,true));assertThatThrownBy(()->changes.commit(admin,store,UUID.randomUUID(),input)).isInstanceOf(WorkforceException.class).extracting("code").isEqualTo("WORKFORCE_ADJUST_CHANGED");var fresh=new Commit(request(),plans.preview(admin,store,request()).fingerprint());jdbc.update("insert into workforce_attendance_sessions(id,tenant_id,store_id,employee_id,schedule_id,in_at,version) select gen_random_uuid(),tenant_id,store_id,employee_id,id,start_at,1 from workforce_schedules where id=?",ids.getFirst());assertThatThrownBy(()->changes.commit(admin,store,UUID.randomUUID(),fresh)).isInstanceOf(WorkforceException.class).extracting("code").isEqualTo("WORKFORCE_ADJUST_CHANGED");for(var id:ids)assertThat(scheduling.find(tenant,id).orElseThrow().version()).isEqualTo(1);}
 @Test void malformedAndForeignTenantTargetsAreRejected(){assertThatThrownBy(()->plans.preview(admin,store,new Request(DATE,early,late,List.of(new Target(ids.getFirst(),1L),new Target(ids.getFirst(),1L))))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);assertThatThrownBy(()->plans.preview(admin,store,new Request(DATE,early,late,List.of(new Target(ids.getFirst(),0L))))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);var foreignActor=new com.rpb.reservation.walkin.api.CurrentActor(UUID.randomUUID(),adminId,"staff",admin.roles(),admin.permissions(),admin.storeIds());assertThatThrownBy(()->plans.preview(foreignActor,store,request())).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(404);}
 @Test void appGateDenialsAndOtherCommandTypesCannotBypassAdjustmentGuards(){var input=new Commit(request(),plans.preview(admin,store,request()).fingerprint());for(var reason:List.of(com.rpb.reservation.appgate.domain.AppGateDenyReason.APP_DISABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.TENANT_APP_NOT_ENABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_NOT_ENABLED)){doReturn(com.rpb.reservation.appgate.domain.AppGateDecision.deny("workforce",tenant,store,"workforce.view",reason)).when(gate).evaluate(any());assertThatThrownBy(()->plans.preview(admin,store,request())).isInstanceOf(WorkforceException.class).extracting("code").isEqualTo(reason.name());assertThatThrownBy(()->changes.commit(admin,store,UUID.randomUUID(),input)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}doReturn(com.rpb.reservation.appgate.domain.AppGateDecision.allow("workforce",tenant,store,"workforce.view")).when(gate).evaluate(any());var command=UUID.randomUUID();new org.springframework.transaction.support.TransactionTemplate(tx).executeWithoutResult(status->bulk.receiptValue(tenant,store,adminId,command,"b".repeat(64),Map.of("created",1)));assertThatThrownBy(()->changes.commit(admin,store,command,input)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(409);for(var id:ids)assertThat(scheduling.find(tenant,id).orElseThrow().version()).isEqualTo(1);}
}
